"""Generated byte contracts only; no authentic source payload or NumPy."""
import io
import math
import struct
import unittest
import zipfile
import decoder as d


def npy(values, dtype='<f8', shape=None, version=1, extra=''):
    header = repr({'descr': dtype, 'fortran_order': False,
                   'shape': (len(values),) if shape is None else shape}) + extra + '\n'
    raw = header.encode(); prefix = b'\x93NUMPY' + bytes((version, 0))
    prefix += len(raw).to_bytes(2 if version == 1 else 4, 'little')
    fmt = dtype[0] + ('d' if dtype[-1] == '8' else 'f')
    return prefix + raw + b''.join(struct.pack(fmt, x) for x in values)


def npz(rows=None, compression=zipfile.ZIP_DEFLATED):
    rows = rows if rows is not None else [('time.npy', npy([10., 10.0001, 10.0002])),
        ('voltage.npy', npy([-70., -10., -65.])), ('stimulus.npy', npy([0., 10., 0.]))]
    out = io.BytesIO()
    with zipfile.ZipFile(out, 'w', compression=compression) as z:
        for name, body in rows:z.writestr(name, body)
    return out.getvalue()


class DecoderTests(unittest.TestCase):
    def test_all_supported_endian_width_version(self):
        for dtype in ['<f4','<f8','>f4','>f8']:
            for version in [1,2,3]:
                x=d.describe_vector(npy([1.,2.,3.],dtype,version=version),axis=True)
                self.assertEqual(x['first_hex'],float(1).hex())
                self.assertEqual(x['count'],3)
    def test_no_offset_or_nominal_clock(self):
        x=d.describe_sweep(npz())
        self.assertEqual(x['channels']['time']['first_hex'],float(10).hex())
        self.assertFalse(x['events_generated']);self.assertFalse(x['sample_rate_reconstruction'])
    def test_frame_complete_count(self):
        with self.assertRaises(d.Refusal):d.describe_frame_times(npy([1.,2.]),3)
    def test_nonmonotone_or_duplicate_time(self):
        for v in [[1.,1.],[2.,1.]]:
            with self.assertRaises(d.Refusal):d.describe_vector(npy(v),axis=True)
    def test_nonfinite_all_channels(self):
        for v in [math.nan,math.inf,-math.inf]:
            with self.assertRaises(d.Refusal):d.describe_vector(npy([v]))
    def test_shapes_are_not_flattened(self):
        for shape in [(1,2),(),(True,),(-1,)]:
            with self.assertRaises(d.Refusal):d.npy_view(npy([1.,2.],shape=shape))
    def test_exact_payload_no_trailing(self):
        for b in [npy([1.])[:-1],npy([1.])+b'x']:
            with self.assertRaises(d.Refusal):d.npy_view(b)
    def test_no_object_pickle_or_executable_header(self):
        for b in [npy([1.]).replace(b'<f8',b'|O8'),
                  npy([1.]).replace(b"False",b"eval('1')")]:
            with self.assertRaises(d.Refusal):d.npy_view(b)
    def test_duplicate_header_rejected(self):
        b=npy([1.]);start=b.index(b'{');end=b.index(b'\n',start)
        h=b[start:end].decode().replace("'shape': (1,)","'shape': (1,), 'descr': '<f8'")+'\n'
        b=b[:8]+len(h).to_bytes(2,'little')+h.encode()+struct.pack('<d',1.)
        with self.assertRaises(d.Refusal):d.npy_view(b)
    def test_exact_npz_members_no_subset(self):
        for rows in [[('time.npy',npy([1.,2.]))],
                     [('time.npy',npy([1.,2.])),('voltage.npy',npy([1.,2.])),('other.npy',npy([1.,2.]))]]:
            with self.assertRaises(d.Refusal):d.describe_sweep(npz(rows))
    def test_equal_lengths(self):
        rows=[('time.npy',npy([1.,2.])),('voltage.npy',npy([1.])),('stimulus.npy',npy([1.,2.]))]
        with self.assertRaises(d.Refusal):d.describe_sweep(npz(rows))
    def test_inner_bomb_admitted_from_headers_before_read(self):
        b=bytearray(npz());p=b.index(b'PK\x01\x02')
        b[p+24:p+28]=(d.VECTOR_FILE_CAP+1).to_bytes(4,'little')
        with self.assertRaises(d.Refusal):d.describe_sweep(bytes(b))
    def test_crc_corruption(self):
        b=bytearray(npz(compression=zipfile.ZIP_STORED));p=b.index(b'PK\x03\x04')
        nl,xl=struct.unpack_from('<HH',b,p+26);b[p+30+nl+xl+15]^=1
        with self.assertRaises(d.Refusal):d.describe_sweep(bytes(b))
    def test_large_gap_is_observed_not_repaired(self):
        x=d.describe_vector(npy([1.,1.0001,10.]),axis=True)
        self.assertEqual(x['maximum_step_hex'],(10.-1.0001).hex())
        self.assertEqual(x['count'],3)
    def test_npz_prefix_and_trailing_are_not_ignored(self):
        for b in [b'junk'+npz(), npz()+b'junk']:
            with self.assertRaises(d.Refusal):d.describe_sweep(b)
    def test_forced_local_zip64_with_normal_central_directory(self):
        for method in (zipfile.ZIP_STORED,zipfile.ZIP_DEFLATED):
            out=io.BytesIO()
            with zipfile.ZipFile(out,'w',compression=method)as z:
                for name in d.EXPECTED:
                    with z.open(name,'w',force_zip64=True)as f:f.write(npy([1.,2.]))
            self.assertEqual(d.describe_sweep(out.getvalue())['channels']['time']['count'],2)
    def test_streamed_signed_data_descriptors_32_and_64(self):
        class ForwardBuffer(io.BytesIO):
            def seek(self,*args):raise OSError('generated unseekable sink')
        for force64 in (False,True):
            out=ForwardBuffer()
            with zipfile.ZipFile(out,'w',compression=zipfile.ZIP_DEFLATED)as z:
                for name in d.EXPECTED:
                    with z.open(name,'w',force_zip64=force64)as f:f.write(npy([1.,2.]))
            self.assertEqual(d.describe_sweep(out.getvalue())['channels']['time']['count'],2)


if __name__ == '__main__':unittest.main()
